insert into public.companies(name)
values ('Storeman Main Company')
on conflict (name) do nothing;

insert into public.warehouses(company_id, name, location)
select c.id, 'Main Warehouse', 'Main'
from public.companies c
where c.name = 'Storeman Main Company'
  and not exists (
    select 1
    from public.warehouses w
    where w.company_id = c.id
  );

-- Backfill existing rows into the main company / main warehouse.
update public.warehouses
set company_id = (
  select id from public.companies
  where name = 'Storeman Main Company'
  limit 1
)
where company_id is null;

update public.materials
set company_id = (
  select id from public.companies
  where name = 'Storeman Main Company'
  limit 1
)
where company_id is null;

update public.suppliers
set company_id = (
  select id from public.companies
  where name = 'Storeman Main Company'
  limit 1
)
where company_id is null;

update public.transactions
set company_id = (
  select id from public.companies
  where name = 'Storeman Main Company'
  limit 1
)
where company_id is null;

update public.sales_orders
set company_id = (
  select id from public.companies
  where name = 'Storeman Main Company'
  limit 1
)
where company_id is null;

update public.materials
set warehouse_id = (
  select w.id
