-- ------------------------------------------------------------
-- 5. Profile creation trigger
-- ------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  default_company uuid;
begin
  select id into default_company
  from public.companies
  where name = 'Storeman Main Company'
  limit 1;

  insert into public.profiles(
    id,
    full_name,
    email,
    role,
    status,
    company_id,
    warehouse_id,
    permissions
  )
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name',''),
    new.email,
    case
      when lower(coalesce(new.email,'')) = lower('ashenafihailay779@gmail.com')
        then 'admin'
      else 'staff'
    end,
    case
      when lower(coalesce(new.email,'')) = lower('ashenafihailay779@gmail.com')
        then 'active'
      else 'pending'
    end,
    default_company,
    null,
    case
      when lower(coalesce(new.email,'')) = lower('ashenafihailay779@gmail.com')
        then jsonb_build_object(
          'dashboard',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'materials',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'stock_in',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'stock_out',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'suppliers',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'warehouses',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'invoicing',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'reports',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'backup',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'users',jsonb_build_object('view',true,'create',true,'update',true,'delete',true),
          'settings',jsonb_build_object('view',true,'create',true,'update',true,'delete',true)
        )
      else private.default_permissions()
    end
  )
  on conflict (id) do update
    set email = excluded.email;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
after insert on auth.users
for each row execute procedure public.handle_new_user();

-- Make sure the already-existing admin account is active.
update public.profiles p
set
  role = 'admin',
  status = 'active',
  email = u.email,
  company_id = coalesce(
    p.company_id,
    (select id from public.companies where name='Storeman Main Company' limit 1)
  ),
  permissions = (
    select jsonb_object_agg(
      f,
      jsonb_build_object('view',true,'create',true,'update',true,'delete',true)
    )
    from unnest(array[
      'dashboard','materials','stock_in','stock_out','suppliers',
      'warehouses','invoicing','reports','backup','users','settings'
    ]) f
  )
from auth.users u
where u.id = p.id
  and lower(u.email) = lower('ashenafihailay779@gmail.com');

-- ------------------------------------------------------------
-- 6. Helper functions for RLS
-- ------------------------------------------------------------

create or replace function private.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select exists(
  select 1
  from public.profiles p
  where p.id = (select auth.uid())
    and p.status = 'active'
);
$$;

create or replace function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select exists(
  select 1
  from public.profiles p
  where p.id = (select auth.uid())
    and p.status = 'active'
    and p.role = 'admin'
);
$$;

create or replace function private.current_company_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
select p.company_id
from public.profiles p
where p.id = (select auth.uid())
limit 1;
$$;

create or replace function private.current_warehouse_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
select p.warehouse_id
from public.profiles p
where p.id = (select auth.uid())
limit 1;
$$;

create or replace function private.can_feature(
  feature_name text,
  action_name text
)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
select
  private.is_admin()
  or (
    private.is_active_user()
    and coalesce(
      ((select p.permissions from public.profiles p
        where p.id=(select auth.uid())) -> feature_name ->> action_name),
      'false'
    )::boolean
  );
$$;

-- Protect users from changing their own security fields.
create or replace function public.prevent_profile_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (select auth.uid()) = old.id and not private.is_admin() then
    if new.role is distinct from old.role
       or new.status is distinct from old.status
       or new.company_id is distinct from old.company_id
       or new.warehouse_id is distinct from old.warehouse_id
       or new.permissions is distinct from old.permissions
       or new.email is distinct from old.email then
      raise exception 'Only an administrator can change role, status, company, warehouse, permissions or email.';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profile_security_guard on public.profiles;
create trigger profile_security_guard
before update on public.profiles
for each row execute procedure public.prevent_profile_escalation();

