-- 9. Policies
-- ------------------------------------------------------------

-- Companies
drop policy if exists companies_select on public.companies;
drop policy if exists companies_insert on public.companies;
drop policy if exists companies_update on public.companies;
drop policy if exists companies_delete on public.companies;

create policy companies_select
on public.companies for select to authenticated
using (
  private.is_active_user()
  and (private.is_admin() or id = private.current_company_id())
);

create policy companies_insert
on public.companies for insert to authenticated
with check (private.is_admin());

create policy companies_update
on public.companies for update to authenticated
using (private.is_admin())
with check (private.is_admin());

create policy companies_delete
on public.companies for delete to authenticated
using (private.is_admin());

-- Warehouses
drop policy if exists warehouses_select on public.warehouses;
drop policy if exists warehouses_insert on public.warehouses;
drop policy if exists warehouses_update on public.warehouses;
drop policy if exists warehouses_delete on public.warehouses;

create policy warehouses_select
on public.warehouses for select to authenticated
using (
  private.is_active_user()
  and (
    private.is_admin()
    or (
      id = private.current_warehouse_id()
      and company_id = private.current_company_id()
    )
  )
);

create policy warehouses_insert
on public.warehouses for insert to authenticated
with check (private.is_admin());

create policy warehouses_update
on public.warehouses for update to authenticated
using (private.is_admin())
with check (private.is_admin());

create policy warehouses_delete
on public.warehouses for delete to authenticated
using (private.is_admin());

-- Profiles
drop policy if exists profiles_select on public.profiles;
drop policy if exists profiles_insert on public.profiles;
drop policy if exists profiles_update on public.profiles;
drop policy if exists profiles_delete on public.profiles;

create policy profiles_select
on public.profiles for select to authenticated
using (
  id = (select auth.uid()) or private.is_admin()
);

-- No direct client inserts. The auth trigger creates profiles.
create policy profiles_update
on public.profiles for update to authenticated
using (
  id = (select auth.uid()) or private.is_admin()
)
with check (
  id = (select auth.uid()) or private.is_admin()
);

create policy profiles_delete
on public.profiles for delete to authenticated
using (private.is_admin());

-- Activity logs
drop policy if exists activity_logs_select on public.activity_logs;
drop policy if exists activity_logs_insert on public.activity_logs;
drop policy if exists activity_logs_update on public.activity_logs;
drop policy if exists activity_logs_delete on public.activity_logs;

create policy activity_logs_select
on public.activity_logs for select to authenticated
using (
  private.is_active_user()
  and (private.is_admin() or user_id=(select auth.uid()))
);

create policy activity_logs_insert
on public.activity_logs for insert to authenticated
with check (
  private.is_active_user()
  and user_id=(select auth.uid())
);

create policy activity_logs_update
on public.activity_logs for update to authenticated
using (private.is_admin())
with check (private.is_admin());

create policy activity_logs_delete
on public.activity_logs for delete to authenticated
using (private.is_admin());

-- ------------------------------------------------------------
-- Data-table policy generator
-- ------------------------------------------------------------

do $$
declare
  t text;
  feature text;
begin
  foreach t in array array['materials','suppliers','transactions','sales_orders']
  loop
    feature := case
      when t='materials' then 'materials'
      when t='suppliers' then 'suppliers'
      when t='transactions' then 'stock_in'
      when t='sales_orders' then 'stock_out'
    end;

    execute format('drop policy if exists %I_select on public.%I', t, t);
    execute format('drop policy if exists %I_insert on public.%I', t, t);
    execute format('drop policy if exists %I_update on public.%I', t, t);
    execute format('drop policy if exists %I_delete on public.%I', t, t);

    execute format(
      'create policy %I_select on public.%I for select to authenticated
       using (
         private.can_feature(%L,''view'')
         and company_id = private.current_company_id()
         and (private.is_admin() or warehouse_id = private.current_warehouse_id())
       )',
      t,t,feature
    );

    execute format(
      'create policy %I_insert on public.%I for insert to authenticated
       with check (
         private.can_feature(%L,''create'')
         and company_id = private.current_company_id()
         and (private.is_admin() or warehouse_id = private.current_warehouse_id())
       )',
      t,t,feature
    );

    execute format(
      'create policy %I_update on public.%I for update to authenticated
       using (
         private.can_feature(%L,''update'')
         and company_id = private.current_company_id()
         and (private.is_admin() or warehouse_id = private.current_warehouse_id())
       )
       with check (
         private.can_feature(%L,''update'')
         and company_id = private.current_company_id()
         and (private.is_admin() or warehouse_id = private.current_warehouse_id())
       )',
      t,t,feature,feature
    );

    execute format(
      'create policy %I_delete on public.%I for delete to authenticated
       using (
         private.can_feature(%L,''delete'')
         and company_id = private.current_company_id()
         and (private.is_admin() or warehouse_id = private.current_warehouse_id())
       )',
      t,t,feature
    );
  end loop;
end
$$;

-- ------------------------------------------------------------
-- 10. Function privileges
-- ------------------------------------------------------------

revoke all on function private.is_active_user() from public;
revoke all on function private.is_admin() from public;
revoke all on function private.current_company_id() from public;
revoke all on function private.current_warehouse_id() from public;
revoke all on function private.can_feature(text,text) from public;

grant execute on function private.is_active_user() to authenticated;
grant execute on function private.is_admin() to authenticated;
grant execute on function private.current_company_id() to authenticated;
grant execute on function private.current_warehouse_id() to authenticated;
grant execute on function private.can_feature(text,text) to authenticated;

-- ------------------------------------------------------------
-- 11. Final admin profile bootstrap
-- ------------------------------------------------------------

insert into public.profiles(
  id,email,full_name,role,status,company_id,warehouse_id,permissions
)
select
  u.id,
  u.email,
  coalesce(u.raw_user_meta_data->>'full_name','System Administrator'),
  'admin',
  'active',
  c.id,
  null,
  (
    select jsonb_object_agg(
      f,
      jsonb_build_object('view',true,'create',true,'update',true,'delete',true)
    )
    from unnest(array[
      'dashboard','materials','stock_in','stock_out','suppliers',
      'warehouses','invoicing','reports','backup','users','settings'
    ]) f
  )
from auth.users u
cross join (
  select id from public.companies
  where name='Storeman Main Company'
  limit 1
) c
where lower(u.email)=lower('ashenafihailay779@gmail.com')
on conflict (id) do update set
  email=excluded.email,
  role='admin',
  status='active',
  company_id=coalesce(public.profiles.company_id, excluded.company_id),
  permissions=excluded.permissions;

